/// Sharded (TF_GLM_KV_SHARD, `shard`): `kv` holds every page's pooled keys alone, `page_bytes` apart, and the latent
/// rows are this rank's own pages at `lat`, `lat_page` apart, through a second, latent table (cuda_kv_shard).
/// `pk`/`pk_page` (upstream's TF_GLM_KV_HOST): the pooled keys sit in device memory beside host pages. // port note
pub const Paged = struct { kv: u64, pages: usize, page_bytes: u64, pk: u64 = 0, pk_page: u64 = 0, lat: u64 = 0, lat_page: u64 = 0, shard: bool = false };

/// A page's bytes for this cache format: every DSA layer's part, then the target MTP head's if it is loaded
/// (bf16 13,056 a row, E4M3 6,960; 11,968 and 6,380 without the head, as beside DFlash2).
pub fn pageBytesOf(w: *const weights.Weights, kv8: bool, head: bool) u64 {
    return (mlaLayers(w) + @intFromBool(head)) * pageCacheBytes(&w.config, kv8);
}

/// Cache `j`'s rows on pages: its part of page 0 at `p.kv`, the others through the table. In E4M3 its codes come
/// first, then the part's scales (`ls`), then the pooled keys. Sharded, the codes and scales are cache `j`'s part of
/// latent page 0 at `p.lat` (through `ltable`) and the pooled keys its part of key page 0 at `p.kv`.
fn onPages(x: *dsa_block.Caches, c: anytype, p: Paged, table: u64, ltable: u64, j: usize, kv8: bool) void {
    if (p.shard) { // port note (af9777b49): the fork's sharded layout
        x.lc = p.lat + j * page_rows * (c.kv_lora + 4);
        x.ls = x.lc + page_rows * c.kv_lora;
        x.pk = p.kv + j * (page_rows / sparse.pool * c.i_dim * 2);
        x.pt = table;
        x.ps = p.page_bytes;
        x.lpt = ltable;
        x.lps = p.lat_page;
        return;
    }
    x.lc = p.kv + j * pageCacheBytes(c, kv8);
    if (kv8) x.ls = x.lc + page_rows * c.kv_lora;
    // port note (af9777b49): upstream's TF_GLM_KV_HOST — the pooled keys in device memory beside the host pages
    x.pk = if (p.pk != 0) p.pk + j * pkCacheBytes(c) else if (kv8) x.ls + page_rows * 4 else x.lc + page_rows * c.kv_lora * 2;
    x.pks = p.pk_page;
